<?php
require_once __DIR__.'/../includes/bootstrap.php';require_login();header('Content-Type: application/json; charset=utf-8');
try{verify_csrf();$albumId=(int)($_POST['album_id']??0);require_album_access($albumId);$file=basename((string)($_POST['file']??''));if(!preg_match('/^pending-[a-f0-9]{20}\.(jpg|png|webp)$/',$file))throw new RuntimeException('Ungültige Coverdatei.');$path=dirname(__DIR__).'/uploads/covers/'.$file;if(!is_file($path))throw new RuntimeException('Cover nicht gefunden.');$accept=($_POST['accept']??'0')==='1';if($accept){$s=$pdo->prepare('UPDATE albums SET cover_file=? WHERE id=? AND (cover_file IS NULL OR cover_file=\'\')');$s->execute([$file,$albumId]);if(!$s->rowCount())@unlink($path);}else{@unlink($path);}echo json_encode(['ok'=>true]);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'message'=>$e->getMessage()]);}
